//! Morph-parity gate (docs/lvgl-factory/10-TREE-PATCH-DESIGN.md D7).
//!
//! Tier 2 — THE dual oracle, two instances per fixture pair
//! (`output/morph-fixtures/*.{base,target,patch}.pb`, generated by
//! `clojure -M:morph-fixtures`):
//!   instance A: `controls_load_ui(base)` → `controls_apply_patch(patch)`
//!   instance B: `controls_load_ui(target)` fresh
//! and asserts `controls_dump_tree(A) == controls_dump_tree(B)` BYTE-EQUAL
//! (uid-tagged, so identity mismatches are visible) AND the framebuffers
//! PIXEL-IDENTICAL.
//!
//! Tier 3 — state-preservation scenarios the dual oracle cannot see (a
//! fresh build never had the state): set live state FIRST (focus + type
//! into a textarea, move a slider, toggle a switch, scroll a list), apply
//! a patch that does not touch those nodes, assert the state survived;
//! plus the AUTHORED-value-changed case (the defined policy: an authored
//! change wins over user state) and the failure contract (base-hash
//! refusal, stale-cache NEEDS_FULL_RELOAD).
#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::missing_docs_in_private_items,
    clippy::missing_errors_doc,
    clippy::missing_panics_doc,
    clippy::doc_markdown,
    clippy::as_conversions,
    clippy::cast_precision_loss,
    missing_docs,
    unused_crate_dependencies,
    reason = "integration tests, not library code"
)]
use lvgl_harness::{ControlsHost, HostConfig, PointerEvent};
use serde_json::Value;

/// Mirrors `grid-pool-ok-cells` in `tools/renderer-gen/src/lvgl_codegen/
/// morph_fixtures.clj` — the grid-container count of the WITHIN-pool walls.
/// Duplicated deliberately, like the other cap mirrors here: reading the number
/// from the generator that produced the fixture would assert nothing.
const GRID_POOL_OK_CELLS: usize = 5;
use std::path::PathBuf;
const WIDTH: u32 = 960;
const HEIGHT: u32 = 540;
const TICK_MS: u32 = lvgl_harness::TICK_MS;
const RENDER_TICKS: u32 = lvgl_harness::RENDER_TICKS;
fn repo_root() -> PathBuf {
    // The parent of this harness crate (renderer/wasm_harness/).
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .to_path_buf()
}
/// Generated by `clojure -M:morph-fixtures --tokens edn/tokens.edn
/// --output output/morph-fixtures` (in-container; `make morph-parity`
/// regenerates).
fn fixtures_dir() -> PathBuf {
    repo_root().join("output/morph-fixtures")
}
fn new_host() -> ControlsHost {
    let config = HostConfig::new(repo_root().join("output/controls.wasm"), WIDTH, HEIGHT)
        .with_wasi_root(repo_root().join("assets"));
    ControlsHost::new(&config).expect("failed to create ControlsHost")
}
fn read_fixture(name: &str, part: &str) -> Vec<u8> {
    let path = fixtures_dir().join(format!("{name}.{part}.pb"));
    std::fs::read(&path).unwrap_or_else(|err| panic!("read {}: {err}", path.display()))
}
/// Read a single-file fixture (`<name>.pb`) — for fixtures deliberately OUTSIDE
/// the base/target/patch triple convention (the dual-oracle scans every
/// `*.base.pb` as a full triple).
fn read_pb(name: &str) -> Vec<u8> {
    let path = fixtures_dir().join(format!("{name}.pb"));
    std::fs::read(&path).unwrap_or_else(|err| panic!("read {}: {err}", path.display()))
}
fn ticks(host: &mut ControlsHost, n: u32) {
    for _ in 0..n {
        host.tick(TICK_MS).expect("tick failed");
    }
}
fn load(host: &mut ControlsHost, data: &[u8]) {
    host.load_ui(data).expect("load_ui failed");
    ticks(host, RENDER_TICKS);
}
/// All fixture case names (sorted) discovered from `*.base.pb`.
fn fixture_cases() -> Vec<String> {
    let mut cases: Vec<String> = std::fs::read_dir(fixtures_dir())
        .expect("morph fixtures missing — run `clojure -M:morph-fixtures` (make morph-parity)")
        .filter_map(Result::ok)
        .filter_map(|entry| {
            entry
                .file_name()
                .to_str()
                .and_then(|n| n.strip_suffix(".base.pb").map(str::to_owned))
        })
        .collect();
    cases.sort();
    assert!(!cases.is_empty(), "no morph fixtures found");
    cases
}
// ── Tree helpers ────────────────────────────────────────────────────

fn parse_tree(host: &mut ControlsHost) -> Value {
    let dump = host.dump_tree().expect("dump_tree");
    serde_json::from_str(&dump).expect("dump_tree JSON")
}
/// Depth-first node search by predicate.
fn find_node<'a>(node: &'a Value, pred: &dyn Fn(&Value) -> bool) -> Option<&'a Value> {
    if pred(node) {
        return Some(node);
    }
    node["children"]
        .as_array()?
        .iter()
        .find_map(|child| find_node(child, pred))
}
fn node_center(node: &Value) -> (i32, i32) {
    let coords = node["coords"].as_array().expect("coords");
    let value = |i: usize| coords[i].as_i64().expect("coord") as i32;
    ((value(0) + value(2)) / 2, (value(1) + value(3)) / 2)
}
/// Framebuffer px → NDC ([-1,1], +x right / +y UP) — the controls_host_message
/// pointer convention (R4). The hit-test routes a click over a clickable widget
/// to the LVGL indev, exactly as the old direct pointer_event did.
fn px_to_ndc(x: i32, y: i32) -> (f64, f64) {
    (
        f64::from(x) / f64::from(WIDTH) * 2.0 - 1.0,
        1.0 - f64::from(y) / f64::from(HEIGHT) * 2.0,
    )
}
/// Click (press + release) at framebuffer coordinates. The 10-tick
/// settles match the visual_regression keyboard precedent: the press
/// must span the indev poll period to register.
fn click(host: &mut ControlsHost, x: i32, y: i32) {
    let (nx, ny) = px_to_ndc(x, y);
    host.pointer(PointerEvent::down(1, nx, ny, 1000))
        .expect("pointer down");
    ticks(host, 10);
    host.pointer(PointerEvent::up(1, nx, ny, 1100))
        .expect("pointer up");
    ticks(host, 10);
}
// ═══════════════════════════════════════════════════════════════════
// Tier 2 — the dual oracle over every fixture pair
// ═══════════════════════════════════════════════════════════════════

#[test]
fn dual_oracle_patched_equals_fresh() {
    for case in fixture_cases() {
        let base = read_fixture(&case, "base");
        let target = read_fixture(&case, "target");
        let patch = read_fixture(&case, "patch");
        // Instance A: base ⊕ patch.
        let mut a = new_host();
        load(&mut a, &base);
        let status = a.apply_patch(&patch).expect("apply_patch call");
        assert_eq!(status, 0, "{case}: controls_apply_patch returned {status}");
        ticks(&mut a, RENDER_TICKS);
        // Instance B: fresh target build, ticked to the SAME total
        // elapsed time as A (load + patch + settle) — animated widgets
        // (kitchen_sink's spinner) are functions of total lv_tick.
        let mut b = new_host();
        load(&mut b, &target);
        ticks(&mut b, RENDER_TICKS);
        let tree_a = a.dump_tree().expect("dump A");
        let tree_b = b.dump_tree().expect("dump B");
        assert_eq!(
            tree_a, tree_b,
            "{case}: uid-tagged tree dumps diverge (morphed ≠ fresh)"
        );
        let fb_a = a.read_framebuffer().expect("fb A");
        let fb_b = b.read_framebuffer().expect("fb B");
        if fb_a != fb_b {
            // Localize the divergence: count + bounding box + one sample
            // pixel pair, so the failing widget is identifiable from the
            // panic alone (no PNG archaeology).
            let (mut min_x, mut min_y, mut max_x, mut max_y) = (u32::MAX, u32::MAX, 0u32, 0u32);
            let mut diff = 0usize;
            let mut sample = (0usize, [0u8; 4], [0u8; 4]);
            for (i, (pa, pb)) in fb_a.chunks(4).zip(fb_b.chunks(4)).enumerate() {
                if pa != pb {
                    if diff == 0 {
                        sample = (
                            i,
                            pa.try_into().expect("rgba"),
                            pb.try_into().expect("rgba"),
                        );
                    }
                    diff += 1;
                    let (x, y) = (i as u32 % WIDTH, i as u32 / WIDTH);
                    min_x = min_x.min(x);
                    min_y = min_y.min(y);
                    max_x = max_x.max(x);
                    max_y = max_y.max(y);
                }
            }
            panic!(
                "{case}: framebuffers diverge — {diff}/{} pixels in bbox \
                 ({min_x},{min_y})-({max_x},{max_y}); first diff at \
                 ({},{}) patched={:?} fresh={:?}",
                fb_a.len() / 4,
                sample.0 as u32 % WIDTH,
                sample.0 as u32 / WIDTH,
                sample.1,
                sample.2,
            );
        }
        // Proxy-bearing fixtures: the sweep after a patch must not touch
        // freed objects (tombstoned registry) — a crash here would trap.
        ticks(&mut a, 2);
    }
}
// ═══════════════════════════════════════════════════════════════════
// Tier 3 — state preservation (what a fresh build can never have)
// ═══════════════════════════════════════════════════════════════════

/// Focus the form textarea and type; returns the typed-into host.
fn focus_and_type(host: &mut ControlsHost, text: &str) {
    let tree = parse_tree(host);
    let ta = find_node(&tree, &|n| n["type"] == "lv_textarea").expect("textarea in form");
    let (x, y) = node_center(ta);
    click(host, x, y);
    for ch in text.chars() {
        host.key(ch as u32).expect("key");
    }
    ticks(host, 10);
}
#[test]
fn typed_text_focus_and_toggles_survive_patch_touching_other_nodes() {
    let base = read_fixture("form_touch_other", "base");
    let patch = read_fixture("form_touch_other", "patch");
    let mut host = new_host();
    load(&mut host, &base);
    // 1. Type into the textarea (focus + content = live user state).
    focus_and_type(&mut host, "xyz");
    let typed = host.focused_text().expect("focused_text").expect("focused");
    assert!(typed.contains("xyz"), "typing failed: {typed:?}");
    // 2. Move the slider by clicking its track at ~80% (user value; the
    //    bound vol subject mirrors it into the readout label).
    let tree = parse_tree(&mut host);
    let slider = find_node(&tree, &|n| n["type"] == "lv_slider").expect("slider");
    let coords = slider["coords"].as_array().unwrap();
    let (x1, y1, x2, y2) = (
        coords[0].as_i64().unwrap() as i32,
        coords[1].as_i64().unwrap() as i32,
        coords[2].as_i64().unwrap() as i32,
        coords[3].as_i64().unwrap() as i32,
    );
    click(&mut host, x1 + (x2 - x1) * 4 / 5, (y1 + y2) / 2);
    // 3. Toggle the switch (CHECKED = user state).
    let tree = parse_tree(&mut host);
    let sw = find_node(&tree, &|n| n["type"] == "lv_switch").expect("switch");
    let (sx, sy) = node_center(sw);
    click(&mut host, sx, sy);
    // Snapshot the user-visible state before the patch.
    let before = parse_tree(&mut host);
    let readout_before = find_node(&before, &|n| {
        n["type"] == "lv_label" && n["text"].as_str().unwrap_or("").parse::<i64>().is_ok()
    })
    .expect("vol readout")["text"]
        .clone();
    assert_ne!(readout_before, "25", "slider click must move the subject");
    let checked_before = find_node(&before, &|n| n["type"] == "lv_switch").unwrap()["checked"]
        .as_bool()
        .unwrap_or(false);
    assert!(checked_before, "switch click must toggle CHECKED");
    // 4. Apply the patch that touches ONLY the sibling status label.
    let status = host.apply_patch(&patch).expect("apply_patch");
    assert_eq!(status, 0, "patch failed: {status}");
    ticks(&mut host, RENDER_TICKS);
    // 5. Everything the user set survives; the patched label changed.
    // (Focus moved to the switch with the last click — click-to-focus —
    // so typed text is asserted via the dumped tree: the textarea
    // renders its content through an internal label. Focus survival
    // itself is pinned by typed_text_survives_container_style_patch.)
    let after = parse_tree(&mut host);
    assert!(
        find_node(&after, &|n| n["text"]
            .as_str()
            .is_some_and(|t| t.contains("xyz")))
        .is_some(),
        "typed textarea content lost after the patch"
    );
    let readout_after = find_node(&after, &|n| {
        n["type"] == "lv_label" && n["text"].as_str().unwrap_or("").parse::<i64>().is_ok()
    })
    .expect("vol readout")["text"]
        .clone();
    assert_eq!(
        readout_before, readout_after,
        "user slider value (subject) must survive"
    );
    let checked_after = find_node(&after, &|n| n["type"] == "lv_switch").unwrap()["checked"]
        .as_bool()
        .unwrap_or(false);
    assert!(checked_after, "user switch toggle must survive");
    assert!(
        find_node(&after, &|n| n["text"] == "saved!").is_some(),
        "the patched status label must show the new text"
    );
}
#[test]
fn typed_text_survives_container_style_patch() {
    // The patch DOES touch the form container (its styles morph in
    // place) but not the textarea's value props — typed text + focus
    // must survive because UPDATE_PROPS never recreates the subtree.
    let base = read_fixture("form_container_style", "base");
    let patch = read_fixture("form_container_style", "patch");
    let mut host = new_host();
    load(&mut host, &base);
    focus_and_type(&mut host, "draft");
    let status = host.apply_patch(&patch).expect("apply_patch");
    assert_eq!(status, 0, "container style patch failed: {status}");
    ticks(&mut host, RENDER_TICKS);
    let text = host
        .focused_text()
        .expect("call")
        .expect("focus must survive a container style morph");
    assert!(text.contains("draft"), "typed text lost: {text:?}");
}
#[test]
fn authored_text_change_overwrites_user_state() {
    // THE DEFINED POLICY: when the AUTHORED value itself changed between
    // base and target, the reconciler applies it — authored wins.
    let base = read_fixture("form_authored_text", "base");
    let patch = read_fixture("form_authored_text", "patch");
    let mut host = new_host();
    load(&mut host, &base);
    focus_and_type(&mut host, "user-typed");
    let status = host.apply_patch(&patch).expect("apply_patch");
    assert_eq!(status, 0, "authored text patch failed: {status}");
    ticks(&mut host, RENDER_TICKS);
    let text = host.focused_text().expect("call").expect("still focused");
    assert_eq!(
        text, "authored2",
        "a changed authored value must overwrite live user state"
    );
}
#[test]
fn scroll_position_survives_patch_touching_other_nodes() {
    let base = read_fixture("scroll_preserve", "base");
    let patch = read_fixture("scroll_preserve", "patch");
    let mut host = new_host();
    load(&mut host, &base);
    // Drag the list up slowly (no release velocity → no scroll throw),
    // then hold before releasing — deterministic final scroll position.
    let tree = parse_tree(&mut host);
    let first_row = find_node(&tree, &|n| n["text"] == "row 0").expect("row 0");
    let (x, y) = node_center(first_row);
    let (px, py) = px_to_ndc(x, y);
    host.pointer(PointerEvent::down(1, px, py, 1000))
        .expect("press");
    ticks(&mut host, 2);
    for step in 1..=12 {
        let (mx, my) = px_to_ndc(x, y - step * 5);
        host.pointer(PointerEvent::mv(1, mx, my, 1000 + (step as u64) * 10))
            .expect("drag");
        ticks(&mut host, 1);
    }
    ticks(&mut host, 12); // hold still — the throw velocity decays to zero
    let (rx, ry) = px_to_ndc(x, y - 60);
    host.pointer(PointerEvent::up(1, rx, ry, 1200))
        .expect("release");
    // Settle until the tree is STABLE (any residual scroll throw /
    // elastic snap must finish before the pre-patch snapshot): three
    // consecutive equal dumps, 5 ticks apart.
    let mut prev = host.dump_tree().expect("dump");
    let mut streak = 0;
    for _ in 0..120 {
        ticks(&mut host, 5);
        let cur = host.dump_tree().expect("dump");
        if cur == prev {
            streak += 1;
            if streak >= 3 {
                break;
            }
        } else {
            streak = 0;
        }
        prev = cur;
    }
    assert!(streak >= 3, "scroll did not settle");
    let before = parse_tree(&mut host);
    let row0_before = node_center(find_node(&before, &|n| n["text"] == "row 0").unwrap());
    assert!(row0_before.1 < y, "the drag must actually scroll the list");
    let status = host.apply_patch(&patch).expect("apply_patch");
    assert_eq!(status, 0, "scroll_preserve patch failed: {status}");
    ticks(&mut host, RENDER_TICKS);
    let after = parse_tree(&mut host);
    let row0_after = node_center(find_node(&after, &|n| n["text"] == "row 0").unwrap());
    assert_eq!(
        row0_before, row0_after,
        "scroll position of the untouched container must survive"
    );
    assert!(
        find_node(&after, &|n| n["text"] == "scrolled").is_some(),
        "the patched status label must show the new text"
    );
}
// ═══════════════════════════════════════════════════════════════════
// Failure + staleness contract (D6)
// ═══════════════════════════════════════════════════════════════════

#[test]
fn base_hash_mismatch_refuses_up_front() {
    // Apply a patch diffed from a DIFFERENT base: PATCH_ERR_BASE_HASH(-2).
    let target = read_fixture("text_update", "target");
    let patch = read_fixture("text_update", "patch");
    // text_update_rev's BASE is text_update's TARGET (same screen map →
    // byte-identical .pb), so its patch matches the loaded state here.
    let rev_patch = read_fixture("text_update_rev", "patch");
    let mut host = new_host();
    load(&mut host, &target); // loaded state == target, patch expects base
    let status = host.apply_patch(&patch).expect("apply_patch");
    assert_eq!(status, -2, "expected PATCH_ERR_BASE_HASH, got {status}");
    // -2 is the one provably-pre-mutation refusal (doc 10 § D6a): it
    // must NOT mark the tree indeterminate — a patch that DOES match
    // the loaded state still applies afterwards.
    let status = host.apply_patch(&rev_patch).expect("apply_patch");
    assert_eq!(
        status, 0,
        "a base-hash refusal must not poison the patch chain, got {status}"
    );
}
/// The duplicate-emit oracle (P0 of the W1 cmd-path battery): after a STYLE
/// morph over a cmd-emitting button, one click emits EXACTLY ONE
/// host_command. The differ strips the unchanged event from the UPDATE
/// payload (morph-invariant), and the reconciler REJECTS any event-carrying
/// UPDATE — so the callback attached at build time stays the only one. A
/// duplicate attach (the closed bug class) would emit two.
#[test]
fn click_after_style_morph_emits_exactly_one_host_command() {
    let base = read_fixture("style_morph_event_btn", "base");
    let patch = read_fixture("style_morph_event_btn", "patch");
    let mut host = new_host();
    load(&mut host, &base);
    let status = host.apply_patch(&patch).expect("apply_patch call");
    assert_eq!(
        status, 0,
        "style_morph_event_btn patch must apply, got {status}"
    );
    ticks(&mut host, RENDER_TICKS);
    // Drain anything staged during build/settle so the count below is
    // exactly the click's emission.
    let stray = host.take_host_commands();
    assert!(
        stray.is_empty(),
        "no host_command expected before the click"
    );
    let tree = parse_tree(&mut host);
    let btn = find_node(&tree, &|n| n["type"] == "lv_button").expect("button in tree");
    let (x, y) = node_center(btn);
    click(&mut host, x, y);
    let cmds = host.take_host_commands();
    assert_eq!(
        cmds.len(),
        1,
        "one click after a style morph must emit exactly one host_command"
    );
}
// ═══════════════════════════════════════════════════════════════════
// Degenerate raw-patch corpus (doc 10 § D6a) — the differ never emits
// these; the RECONCILER's contract is: exact PATCH_ERR_* code, the tree
// marked INDETERMINATE on every (possibly-)mutating abort, further
// patches refused (-6), composite setters demanding the full reload,
// and a full load recovering cleanly. Partial application is thereby
// proven impossible to compound silently.
// ═══════════════════════════════════════════════════════════════════

fn degenerate_dir() -> PathBuf {
    fixtures_dir().join("degenerate")
}
/// The GRID PATCH_ERR_POOL (-4) case now has a dedicated fixture + test
/// (`grid_pool_over_demand_replace_refuses_before_deleting_target`): the
/// demand-aware grid check makes a moderate pathological screen enough to
/// trigger it, and the refusal is proven to sit BEFORE any mutation. Pool
/// pressure DID become a deployment concern once — through a renderer LEAK,
/// not a pathological screen: see
/// `same_name_ttf_style_morphs_never_exhaust_binfont_registry`, which pins the
/// resolve_font per-name cache that closed it (and doubles as the -4 refusal's
/// live oracle when the cache regresses).
fn degenerate_cases() -> Vec<String> {
    let mut cases: Vec<String> = std::fs::read_dir(degenerate_dir())
        .expect("degenerate fixtures missing — run `clojure -M:morph-fixtures`")
        .filter_map(Result::ok)
        .filter_map(|entry| {
            entry
                .file_name()
                .to_str()
                .and_then(|n| n.strip_suffix(".base.pb").map(str::to_owned))
        })
        .collect();
    cases.sort();
    assert!(!cases.is_empty(), "no degenerate fixtures found");
    cases
}
fn read_degenerate(case: &str, suffix: &str) -> Vec<u8> {
    let path = degenerate_dir().join(format!("{case}.{suffix}"));
    std::fs::read(&path).unwrap_or_else(|err| panic!("read {}: {err}", path.display()))
}
#[test]
fn degenerate_raw_patches_abort_loudly_with_indeterminate_contract() {
    const PATCH_ERR_BASE_HASH: i32 = -2;
    const PATCH_ERR_INDETERMINATE: i32 = -6;
    for case in degenerate_cases() {
        let base = read_degenerate(&case, "base.pb");
        let patch = read_degenerate(&case, "patch.pb");
        let valid = read_degenerate(&case, "valid.patch.pb");
        let expect: i32 = String::from_utf8(read_degenerate(&case, "expect"))
            .expect("expect utf8")
            .trim()
            .parse()
            .expect("expect rc");
        let mut host = new_host();
        load(&mut host, &base);
        let rc = host.apply_patch(&patch).expect("apply_patch call");
        assert_eq!(rc, expect, "{case}: expected rc {expect}, got {rc}");
        if expect == 0 {
            // The vacuous (empty-ops) apply: wire-valid, hash-checked,
            // and the state hash ADVANCES to target_hash — re-applying
            // the same patch now refuses against the new hash.
            let rc2 = host.apply_patch(&patch).expect("re-apply");
            assert_eq!(
                rc2, PATCH_ERR_BASE_HASH,
                "{case}: a vacuous apply must advance the state hash"
            );
            // …and the cached .pb is stale like any successful patch.
            let err = host
                .set_theme_dark(1)
                .expect_err("cache must be stale after a vacuous apply");
            assert!(
                err.to_string().contains("returned error: 1"),
                "{case}: expected status 1 (NEEDS_FULL_RELOAD), got: {err}"
            );
            continue;
        }
        // (1) The tree is INDETERMINATE: even a perfectly VALID patch
        //     (diffed from this exact base) refuses until a full load.
        let rc_valid = host.apply_patch(&valid).expect("apply valid patch");
        assert_eq!(
            rc_valid, PATCH_ERR_INDETERMINATE,
            "{case}: a valid patch must refuse with PATCH_ERR_INDETERMINATE \
             after an abort (got {rc_valid}) — silent partial application!"
        );
        // (2) Composite setters demand the full reload instead of
        //     silently rebuilding from a cache the tree diverged from.
        let err = host
            .set_theme_dark(1)
            .expect_err("composite setter must signal NEEDS_FULL_RELOAD");
        assert!(
            err.to_string().contains("returned error: 1"),
            "{case}: expected status 1 (NEEDS_FULL_RELOAD), got: {err}"
        );
        // (3) Ticking a half-mutated tree must not trap (registry
        //     coherence: deleted subtrees are unregistered/tombstoned).
        ticks(&mut host, 2);
        // (4) A full load recovers cleanly: the indeterminate flag and
        //     staleness clear, the theme flips, and the SAME valid
        //     patch now applies.
        load(&mut host, &base);
        host.set_theme_dark(0)
            .expect("a full load must clear the indeterminate state");
        ticks(&mut host, 2);
        let rc_recovered = host.apply_patch(&valid).expect("apply after recovery");
        assert_eq!(
            rc_recovered, 0,
            "{case}: the valid patch must apply after the full-reload recovery"
        );
        ticks(&mut host, 2);
    }
}
// ═══════════════════════════════════════════════════════════════════
// T18 / D-WB9 — grid-template pool: demand-aware REPLACE refusal
// ═══════════════════════════════════════════════════════════════════

/// A REPLACE whose new subtree's grid demand OUTRUNS the write-once template
/// pool must refuse LOUDLY (-4) BEFORE any mutation, so the pre-patch tree is
/// unchanged (the old target survives). The fixture is sized so
/// patch_pools_low's FIXED PATCH_GRID_HEADROOM margin passes (the base leaves
/// the pool empty) — only the DEMAND-AWARE check catches the 33-grid subtree.
///
/// Pre-fix (no demand-aware check) this test is RED both ways: the fixed margin
/// passed, REPLACE deleted the old target FIRST, then the streaming build hit
/// the pool wall mid-subtree — leaving a corrupted half-tree (old target gone)
/// and returning -5, not -4.
#[test]
fn grid_pool_over_demand_replace_refuses_before_deleting_target() {
    const PATCH_ERR_POOL: i32 = -4;
    let base = read_pb("grid_pool_base");
    let exhaust = read_pb("grid_pool_over_demand");
    let mut host = new_host();
    load(&mut host, &base);
    let before = host.dump_tree().expect("dump before");
    assert!(
        before.contains("REPLACE ME"),
        "target must be present in the base tree"
    );

    let rc = host.apply_patch(&exhaust).expect("apply exhaust patch");
    assert_eq!(
        rc, PATCH_ERR_POOL,
        "over-demand grid REPLACE must refuse with PATCH_ERR_POOL (-4), got {rc}"
    );

    // The refusal sits BEFORE the delete: the live tree is byte-identical to
    // pre-patch, the old target intact.
    let after = host.dump_tree().expect("dump after");
    assert_eq!(
        before, after,
        "a refused REPLACE must leave the tree UNCHANGED (old subtree intact)"
    );
    assert!(
        after.contains("REPLACE ME"),
        "the old target must survive a refused over-demand REPLACE"
    );
    ticks(&mut host, RENDER_TICKS);
}

/// A large-but-WITHIN-pool grid REPLACE succeeds and swaps the target for the
/// grid subtree — the happy-path companion to the refusal above (the
/// demand-aware check must not over-refuse a legitimate grid subtree).
#[test]
fn grid_pool_within_pool_replace_succeeds() {
    let base = read_pb("grid_pool_base");
    let ok = read_pb("grid_pool_within_pool");
    let mut host = new_host();
    load(&mut host, &base);
    let rc = host.apply_patch(&ok).expect("apply ok patch");
    assert_eq!(rc, 0, "within-pool grid REPLACE must succeed, got {rc}");
    ticks(&mut host, RENDER_TICKS);
    let after = host.dump_tree().expect("dump after");
    assert!(
        !after.contains("REPLACE ME"),
        "the target must be replaced by the grid subtree"
    );
    assert_grid_wall_laid_out(&after, GRID_POOL_OK_CELLS, "within-pool REPLACE");
}

/// The grid containers of a within-pool wall must actually LAY OUT — distinct,
/// non-degenerate rects — not merely be present in the tree.
///
/// Without this, `rc == 0` plus "the old target is gone" proves only that the
/// guard did not OVER-refuse. Every container could have collapsed to a
/// zero-area box stacked at the origin (which is exactly what pool exhaustion
/// degrades a grid container to) and the assertions above would still pass.
fn assert_grid_wall_laid_out(dump: &str, expected_cells: usize, case: &str) {
    let tree: Value = serde_json::from_str(dump).expect("dump_tree JSON");
    let mut rects: Vec<(i64, i64, i64, i64)> = Vec::new();
    collect_rects(&tree, &mut rects);
    let sized: Vec<_> = rects.iter().filter(|(_, _, w, h)| *w > 0 && *h > 0).collect();
    assert!(
        sized.len() >= expected_cells,
        "{case}: only {} node(s) have a non-degenerate rect, expected at least \
         {expected_cells} laid-out grid containers — a collapsed wall is what \
         pool exhaustion produces, and rc==0 alone cannot tell them apart",
        sized.len()
    );
    let distinct: std::collections::BTreeSet<_> = sized.iter().collect();
    assert!(
        distinct.len() > 1,
        "{case}: every laid-out node shares one rect — the wall did not lay out, \
         it stacked"
    );
}

/// Collect each node's rect from a `controls_dump_tree` payload.
///
/// The dump emits `"coords":[x1,y1,x2,y2]` — an LVGL area, INCLUSIVE on both
/// ends, not an (x, y, w, h) tuple. Getting that wrong yields zero rects and an
/// assertion that looks like a renderer failure; it is worth naming here since
/// the shape is not guessable from the test side.
fn collect_rects(node: &Value, out: &mut Vec<(i64, i64, i64, i64)>) {
    if let Some(obj) = node.as_object() {
        if let Some(c) = obj.get("coords").and_then(Value::as_array) {
            let v: Vec<i64> = c.iter().filter_map(Value::as_i64).collect();
            if let [x1, y1, x2, y2] = v[..] {
                // Inclusive area -> width/height.
                out.push((x1, y1, x2 - x1 + 1, y2 - y1 + 1));
            }
        }
        if let Some(kids) = obj.get("children").and_then(Value::as_array) {
            for k in kids {
                collect_rects(k, out);
            }
        }
    }
}

/// The DISCRIMINATOR the over-demand INSERT test cannot be on its own.
///
/// Two sites return PATCH_ERR_POOL on the INSERT path: `patch_pools_low`'s
/// FIXED margin, checked at the op top, and `grid_demand_exceeds_pool`, the
/// demand-aware check the over-demand test NAMES. An assertion of `rc == -4`
/// cannot say which fired, and today the answer is a property of FIXTURE
/// SIZING (the base leaves the pool empty so the fixed margin passes), not of
/// anything asserted. Let `grid_pool_base` gain a grid container and the fixed
/// margin starts firing first: both over-demand tests stay GREEN while
/// silently testing a different door.
///
/// A within-pool INSERT must SUCCEED, and only the demand-aware check permits
/// that — the fixed margin, were it the site refusing, would refuse this too.
/// So this test going RED is the signal that the over-demand tests have
/// changed doors.
#[test]
fn grid_pool_within_pool_insert_succeeds() {
    let base = read_pb("grid_pool_base");
    let ok = read_pb("grid_pool_insert_within_pool");
    let mut host = new_host();
    load(&mut host, &base);
    let rc = host.apply_patch(&ok).expect("apply within-pool insert");
    assert_eq!(
        rc, 0,
        "a within-pool grid INSERT must SUCCEED, got {rc} — if this is -4, the \
         FIXED patch_pools_low margin is now the site refusing, which means the \
         over-demand INSERT test is no longer exercising the demand-aware check \
         its name claims"
    );
    ticks(&mut host, RENDER_TICKS);
    let after = host.dump_tree().expect("dump after");
    assert_grid_wall_laid_out(&after, GRID_POOL_OK_CELLS, "within-pool INSERT");
}

/// An INSERT whose payload subtree's grid demand OUTRUNS the write-once
/// template pool must refuse LOUDLY (-4) BEFORE building anything, so the
/// pre-patch tree is unchanged.
///
/// INSERT carries the SAME `grid_demand_exceeds_pool` guard REPLACE does,
/// placed before both `find_uid_obj(parent)` and `decode_op_node`. Existing
/// INSERT fixtures already traverse that guard — `duplicate_insert_uid`
/// reaches a uid-registration failure only by passing it — but none had ever
/// driven it to REFUSE, and a branch nobody has watched fire is
/// indistinguishable from an absent one.
///
/// Pre-guard (delete the INSERT-side `grid_demand_exceeds_pool` call) this
/// test is RED: the base leaves the pool empty so patch_pools_low's FIXED
/// margin passes, the streaming build then hits the pool wall, and the op
/// returns -5 with the wall parented but degraded to non-grid (on exhaustion
/// the col+row allocs fail together — see renderer.c's alloc_grid_template
/// pairing note — so nothing is stranded half-built).
#[test]
fn grid_pool_over_demand_insert_refuses_before_building() {
    const PATCH_ERR_POOL: i32 = -4;
    let base = read_pb("grid_pool_base");
    let exhaust = read_pb("grid_pool_insert_over_demand");
    let mut host = new_host();
    load(&mut host, &base);
    let before = host.dump_tree().expect("dump before");
    // Non-vacuity guard: the `before == after` check below is a ZERO-DELTA
    // assertion, so its PASS value equals its nothing-ran value — it would hold
    // trivially if dump_tree returned an empty (or identically-failing) string
    // both times, proving nothing. Pin that the base tree really loaded first,
    // so the equality can only pass by the refusal genuinely leaving it intact.
    assert!(
        before.contains("stays"),
        "base tree must actually be loaded for the unchanged-tree assertion to mean anything"
    );

    let rc = host
        .apply_patch(&exhaust)
        .expect("apply insert exhaust patch");
    assert_eq!(
        rc, PATCH_ERR_POOL,
        "over-demand grid INSERT must refuse with PATCH_ERR_POOL (-4), got {rc}"
    );

    // The refusal sits BEFORE the build: the live tree is byte-identical to
    // pre-patch — nothing parented, nothing half-built.
    let after = host.dump_tree().expect("dump after");
    assert_eq!(
        before, after,
        "a refused INSERT must leave the tree UNCHANGED (nothing built)"
    );
    ticks(&mut host, RENDER_TICKS);
}
